layui.use(['form', 'layer'], function () {
  var form = layui.form;
  var layer = layui.layer;
  var $ = layui.$;

  var $form = $('#productCommentForm');
  var $content = $('#productCommentContent');

  function getAvatarText(name) {
    var s = String(name || '').trim().replace(/\s+/g, '');
    if (!s) return '访';
    var chars = Array.from(s);
    if (chars.length === 1) return chars[0];
    if (/[\u4e00-\u9fa5]/.test(chars[0])) return chars[0];
    return (chars[0] + chars[1]).toUpperCase();
  }

  $('[data-avatar-name]').each(function () {
    var name = $(this).attr('data-avatar-name');
    $(this).text(getAvatarText(name));
  });

  $('#commentImageTrigger').on('click', function () {
    $('#commentImageInput').trigger('click');
  });

  $('#commentImageInput').on('change', function () {
    var files = this.files || [];
    var $preview = $('#commentImagePreview');
    $preview.empty();
    Array.prototype.forEach.call(files, function (file) {
      if (!file.type || file.type.indexOf('image/') !== 0) return;
      var url = URL.createObjectURL(file);
      var html = '<span class="comment-image-thumb"><img src="' + url + '" alt="image"></span>';
      $preview.append(html);
    });
  });

  form.on('submit(submitProductComment)', function () {
    var content = String($content.val() || '').trim();
    if (!content) {
      layer.msg('请输入评论内容', { icon: 2 });
      return false;
    }
    if (content.length > 500) {
      layer.msg('评论内容不能超过 500 字', { icon: 2 });
      return false;
    }

    var load = layer.load(2, { shade: [0.2, '#000'] });
    $.ajax({
      url: '/products/comment',
      type: 'POST',
      data: new FormData($form[0]),
      processData: false,
      contentType: false,
      dataType: 'json',
      success: function (res) {
        layer.close(load);
        if (res.code === 200) {
          layer.msg(res.msg || '提交成功', { icon: 1, time: 1200 }, function () { location.reload(); });
          return;
        }
        if (res.code === 401 && res.data && res.data.redirect) {
          window.location.href = res.data.redirect + '?redirect=' + encodeURIComponent(location.pathname + location.search);
          return;
        }
        layer.msg(res.msg || '提交失败', { icon: 2 });
      },
      error: function () {
        layer.close(load);
        layer.msg('网络错误，请稍后重试', { icon: 2 });
      }
    });
    return false;
  });

  $('[data-comment-images]').each(function (index, el) {
    var $el = $(el);
    if (!$el.attr('id')) {
      $el.attr('id', 'pc-comment-images-' + index);
    }
    $el.find('a').on('click', function (event) {
      event.preventDefault();
      layer.photos({
        photos: '#' + $el.attr('id'),
        anim: 5,
        shade: 0.75,
        shadeClose: true
      });
    });
  });

  (function bindApplyModule() {
    var $module = $('[data-apply-module]');
    if (!$module.length) {
      return;
    }

    var jumpUrl = String($module.attr('data-jump-url') || '').trim();
    var qrcodeSrc = String($module.attr('data-jump-qrcode') || '').trim();
    var $primary = $module.find('[data-apply-primary]');
    var $feedback = $module.find('[data-apply-feedback]');
    var $qrCard = $module.find('[data-apply-qr-card]');
    var $qrImage = $module.find('[data-apply-qr-image]');
    var $qrLoading = $module.find('[data-apply-qr-loading]');
    var $copyBtn = $module.find('[data-apply-copy]');
    var applyBusy = false;
    var qrcodeReady = false;

    function setFeedback(text, type) {
      if (!$feedback.length) return;
      $feedback.removeClass('is-success is-error');
      if (!text) {
        $feedback.text('');
        return;
      }
      if (type === 'success') $feedback.addClass('is-success');
      if (type === 'error') $feedback.addClass('is-error');
      $feedback.text(text);
    }

    function buildQrcodeUrl() {
      if (!jumpUrl) return '';
      return '/share/qrcode.png?target=' + encodeURIComponent(jumpUrl);
    }

    function ensureQrcode() {
      if (qrcodeReady || !$qrImage.length) return;
      var img = $qrImage.get(0);
      var src = qrcodeSrc || buildQrcodeUrl();
      if (!src) {
        setFeedback('暂无法生成二维码，请直接点击立即申请。', 'error');
        return;
      }
      $qrLoading.show();
      $qrImage.hide();
      img.onload = function () {
        qrcodeReady = true;
        $qrLoading.hide();
        $qrImage.show();
      };
      img.onerror = function () {
        $qrLoading.text('二维码加载失败，请复制链接后在微信打开');
        setFeedback('二维码加载失败，请复制链接后在微信打开。', 'error');
      };
      img.src = src;
    }
    ensureQrcode();

    $primary.on('click', function (event) {
      if (!jumpUrl) return;
      event.preventDefault();
      if (applyBusy) return;
      applyBusy = true;
      var oldText = $primary.text();
      $primary.addClass('is-loading').text('跳转中...');
      setFeedback('正在为你打开申请页面...', '');
      var opened = window.open(jumpUrl, '_blank', 'noopener');
      if (!opened) {
        setFeedback('浏览器拦截了新窗口，请使用微信扫码申请。', 'error');
      } else {
        setFeedback('已为你打开申请页面。', 'success');
      }
      setTimeout(function () {
        applyBusy = false;
        $primary.removeClass('is-loading').text(oldText);
      }, 900);
    });

    $copyBtn.on('click', function () {
      if (!jumpUrl) return;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(jumpUrl).then(function () {
          setFeedback('申请链接已复制。', 'success');
        }).catch(function () {
          setFeedback('复制失败，请手动复制地址栏链接。', 'error');
        });
        return;
      }
      var $temp = $('<input type="text">').val(jumpUrl).appendTo('body');
      $temp.select();
      try {
        document.execCommand('copy');
        setFeedback('申请链接已复制。', 'success');
      } catch (_err) {
        setFeedback('复制失败，请手动复制地址栏链接。', 'error');
      }
      $temp.remove();
    });
  })();
});
